insert into public.categories (slug, name, headline, description, seo_title, seo_description, sort_order) values ('restaurants', 'Restaurants', 'Where Branson eats', 'Award-winning barbecue, century-old cafés, wood-fired pubs and lakeside dining — all locally owned.', 'Best Local Restaurants in Branson, MO | Where to Eat & Dine', 'Find the best locally owned restaurants in Branson, Missouri — BBQ, pizza, Mexican, diners, cafés, breweries and more, with addresses, phone numbers and directions.', 0) on conflict (slug) do nothing;
insert into public.categories (slug, name, headline, description, seo_title, seo_description, sort_order) values ('hotels', 'Hotels & Lodging', 'Where to stay in Branson', 'Hotels, lakefront resorts, inns, nightly condos and RV parks for every kind of Branson getaway.', 'Hotels & Where to Stay in Branson, MO | Local Lodging', 'Locally owned hotels, inns, resorts, condos and RV parks in Branson, Missouri and Table Rock Lake — compare and book direct.', 1) on conflict (slug) do nothing;
insert into public.categories (slug, name, headline, description, seo_title, seo_description, sort_order) values ('shows', 'Branson Shows', 'The Live Entertainment Capital', 'Theatres, tribute acts, gospel, comedy and family shows on 76 Country Boulevard and beyond.', 'Branson Shows & Theatres | Live Entertainment in Branson, MO', 'Browse live shows and theatres in Branson, Missouri — The Duttons, Clay Cooper, Jim Stafford, Shepherd of the Hills and more. Get tickets and directions.', 2) on conflict (slug) do nothing;
insert into public.categories (slug, name, headline, description, seo_title, seo_description, sort_order) values ('shopping', 'Shopping', 'Shop local, shop Branson', 'Downtown classics, Branson Landing boutiques, antiques, galleries and Christmas shops.', 'Shopping in Branson, MO | Local Shops, Boutiques & Antiques', 'Discover locally owned shops in Branson, Missouri — Dick''s 5 & 10, Mulberry Mill, Kringle''s, antiques, galleries and gift shops.', 3) on conflict (slug) do nothing;
insert into public.categories (slug, name, headline, description, seo_title, seo_description, sort_order) values ('specialty-shops', 'Specialty Shops', 'One-of-a-kind finds', 'Bakeries, spas, wineries, sweets, formalwear, craft makers and services you won''t find anywhere else.', 'Specialty Shops in Branson, MO | Bakeries, Spas, Gifts & More', 'Unique locally owned specialty shops in Branson, Missouri — bakeries, day spas, wineries, sweets, jewelry, formalwear and handmade goods.', 4) on conflict (slug) do nothing;
insert into public.categories (slug, name, headline, description, seo_title, seo_description, sort_order) values ('things-to-do', 'Things To Do', 'Make a day of it', 'Escape rooms, distilleries, marinas, ghost tours, e-bikes, bowling and nightlife.', 'Things to Do in Branson, MO | Attractions, Tours & Nightlife', 'The best local things to do in Branson, Missouri — escape rooms, marinas on Table Rock Lake, distilleries, ghost tours, e-bike rentals and nightlife.', 5) on conflict (slug) do nothing;
