insert into public.categories (slug, name, headline, description, seo_title, seo_description, sort_order) values ('day-trips', 'Day Trips', 'Beyond Branson', 'Easy drives from Branson — Eureka Springs, Table Rock Lake towns and Ozark hideaways.', 'Day Trips from Branson, MO | Nearby Ozarks Destinations', 'Plan a day trip from Branson, Missouri — nearby Ozarks towns, attractions and locally owned stops worth the drive.', 8) on conflict (slug) do nothing;
