insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('branson-knights', 'Branson Knights, LLC', 'OUR HOME IS YOUR CASTLE', 'Branson Knights, LLC is a family-owned, Branson-based company. Don, Tamara and their five children love calling Branson home and they hope you feel part of their Branson family while you stay here. 3rd party, impersonal property managers are never utilized. They believe in providing customized, personal service to you and yours. See you soon! Don and Tamara hope your stay at one of their condos at The Pointe Royale Golf Village is the most relaxing and comfortable you''ve ever experienced in Branson. If at any point you need help or advice during your stay, please reach out to Don and he will help! They know all the ins and outs of what to do with children in the area (including all the free stuff)!', null, 'Branson', 'MO', null, null, null, 'https://www.bransonknights.com/', 'https://www.facebook.com/BransonKnightsLLC/', null, 'https://www.google.com/maps/place/Branson+Knights,+LLC/@36.696887,-93.1551307,17z/data=!3m1!4b1!4m5!3m4!1s0x87cf07476810e9e1:0xc947594c1e2e2acd!8m2!3d36.6968827!4d-93.152942', '/legacy/branson-knights.png', 'https://www.bransonlocalbusinesses.com/index_htm_files/40111@2x.png', '[]'::jsonb, true, true, 5) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'branson-knights' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('branson-duck-tours', 'Branson Duck Tours', 'Ready to set sail?', 'Ready to set sail? As part of the Branson community, we welcome you and your loved ones to a once-in-a-lifetime experience. Journey by land through the streets of Branson, singing songs, hearing jokes and tall tales, and learning local history. Then, without getting up from your seat, you''ll splash on to Lake Taneycomo, where you''ll have the opportunity to see downtown Branson and 1931 Historic Taneycomo Bridge from the water, a memorable experience you''ll cherish for ages! Tours last approximately 60-90 minutes. Book now to purchase your seats on this beloved Branson tradition that will leave you filled with laughter and delight.', '1940 W 76 Country Blvd', 'Branson', 'MO', '65616', '(417) 598-9099', null, 'https://bransonducktours.com/', 'https://www.facebook.com/bransonducktours', null, null, '/legacy/branson-duck-tours.png', 'https://www.bransonlocalbusinesses.com/index_htm_files/47694@2x.png', '[]'::jsonb, true, true, 6) on conflict (slug) do nothing;
