insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('kings-river-marina', 'Kings River Marina', null, 'Welcome to Kings River Marina! We are located on the quiet side of Table Rock Lake, four miles south of Shell Knob on Highway 39 and approximately 40 short minutes from Branson! Kings River Marina offers boat rentals, annual/nightly slip rentals, boat repair, pump outs, and a full-service marine store including fuel, beer, ice, bait, tackle, Liquid Force wakeboards, clothing, and water toys.', '27504 Big Rock Rd', 'Shell Knob', 'MO', '65747', '(417) 858-0223', null, 'https://kingsrivermarina.com/', 'https://www.facebook.com/KingsRiverMarina/', null, null, null, null, '[]'::jsonb, false, true, 36) on conflict (slug) do nothing;
