insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('cape-fair-marina', 'Cape Fair Marina', null, 'If you''re planning a trip to Table Rock Lake, this is one destination you won''t want to miss! Cape Fair Marina is a full-service marina located near the popular James River Arm of the lake in Cape Fair, Missouri, where the water is clean and the fishing is great. We''re the nicest, full-service marina on the lake. Come check us out and you''ll agree! Our modern facilities include a full-service gas dock with pump-outs, beer, gas, ice, and all of the convenience store items you''d expect. Launch your own boat at a nearby US Army Corps of Engineers launch ramp or rent one from us. We have a full line of pontoons, tritoons, wake and ski boats, and fishing boats to choose from. Plus we have paddle boards for rent.', '1500 Shadrack Rd', 'Cape Fair', 'MO', '65624', '(417) 538-4164', null, 'https://capefairmarina.com/', 'https://www.facebook.com/#!/pages/Cape-Fair-Marina/126435147646', null, null, null, null, '[]'::jsonb, false, true, 37) on conflict (slug) do nothing;
