insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'cape-fair-marina' and c.slug = 'things-to-do' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('capones-speakeasy', 'Capone''s Speakeasy', null, 'Welcome to a hidden drinking spot birthed in 1903 with a rich Branson past. Each sip is an experience layered with the ghosts of history, including those of the great writer Harold Bell Wright who wrote Shepherd of the Hills in our very own building. Capone''s inspires a time and place thought to be lost to the ages; a celebration of the type of cocktailing that is more of an art than a pastime. Come enjoy our little hideaway with an evening drink, delectable tapa, live music, and great people looking to welcome you into our home.', '158 Pointe Royale Dr', 'Branson', 'MO', '65616', '(417) 544-0844', null, 'https://www.caponesspeakeasybranson.com/', 'https://www.facebook.com/caponesspeakeasybranson', null, null, null, null, '[]'::jsonb, false, true, 38) on conflict (slug) do nothing;
