insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('branson-brick-exchange', 'Branson Brick Exchange & Minifig Market', null, 'Branson Brick Exchange & Minifig Market is a family-oriented, veteran-owned shop built for LEGO® fans of all ages. We specialize in buying, selling, and trading both new and pre-loved LEGO® sets, bricks, and mini figures—because every piece has a story, and every build deserves a second life. Whether you''re hunting for a rare mini figure, looking to trade in sets for in-store credit, or just want to spark creativity with your kids, we''re here to bring the joy of building to our community. As a family business, we value connection, imagination, and fun and as a veteran-owned store, we''re proud to serve with integrity, dedication, and heart. At Branson Brick Exchange & Minifig Market it''s more than bricks, it''s about building memories together.', '203 W Atlantic St', 'Branson', 'MO', '65616', '(417) 973-2100', null, null, 'https://www.facebook.com/p/Branson-Brick-Exchange-Minifig-Market-LLC-61579590417990/', null, null, null, null, '[]'::jsonb, false, true, 107) on conflict (slug) do nothing;
