insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('sky-talk-communications', 'Sky Talk Communications', 'Rent Two-Way Radios', 'Sky Talk Communications offers affordable, high-quality radio rentals starting at just $1.99 per day. We also provide flexible weekly and monthly rental options to fit your needs and budget. Serving the Branson, Missouri area, our experienced team is ready to help you find the right communication solution for your event or project. Sky Talk Communications is your trusted partner for affordable, high-quality radio rentals in the Branson, Missouri area. With years of experience and a commitment to professionalism, we provide reliable communication solutions without stretching your budget.', null, 'Branson', 'MO', '65616', '(417) 973-2465', null, 'http://skytalkcommunications.com/', 'https://www.facebook.com/p/Sky-Talk-communications-61558580682036/', null, null, null, null, '[]'::jsonb, false, true, 108) on conflict (slug) do nothing;
