insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('truth-traveler', 'Truth Traveler', null, 'Ready to journey like never before? Truth Traveler is not just an attraction—it''s a groundbreaking 5D experience that takes you through biblical history! Using cutting-edge VR technology, we''ll transport you to pivotal moments in time, from the wonder of Creation to the miracle of Christ''s resurrection. Witness the towering Ark, stand at the foot of the Tower of Babel, and step into the story of redemption as it unfolds.', '1 Andy Williams Blvd.', 'Branson', 'MO', '65616', '(417) 334-4500', null, 'https://truthtraveler.com/branson', 'https://www.facebook.com/TruthTravelerBranson', null, null, null, null, '[]'::jsonb, false, true, 109) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'truth-traveler' and c.slug = 'things-to-do' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('the-haunted-taxi-ghost-tour', 'The Haunted Taxi Ghost Tour', 'Family Friendly Ghost Tours', 'Family Friendly Ghost Tours. The Official Haunted Taxi Ghost Tours, Part of Fearcation Haunted Travel App. At UHaunted We Make Fear Fun Year-Round in Atchison, KS; Branson, MO; Dodge City, KS; Kansas City, MO; Olathe, KS & Omaha, NE. The Haunted Taxi Ghost Tour: This Branson MO based Night Ghost Tour takes you to one of the most haunted mountain towns in the USA. A daytime Branson MO based ghost tour also takes you to one of the most haunted mountain towns in the USA in a Rock"N" Haunted Taxi Cab.', null, 'Branson', 'MO', null, '(913) 205-9775', null, 'https://www.hauntedtaxi.com/', 'https://www.facebook.com/UHaunted/', null, null, null, null, '[{"label":"Haunted Taxi Night Ghost Tour (Branson)","url":"https://www.hauntedtaxi.com/service-page/the-haunted-taxi-ghost-tour-branson-mo-1?referral=service_list_widget"},{"label":"Rock N Haunted Mountain History Day Tour (Branson)","url":"https://www.hauntedtaxi.com/service-page/rock-n-haunted-mountain-history-branson?referral=service_list_widget"},{"label":"Ghost Tour Pre-Show Video","url":"https://www.youtube.com/watch?v=9LEcS1KAUO8"}]'::jsonb, false, true, 110) on conflict (slug) do nothing;
