insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('totally-rad-e-bikes', 'Totally Rad E-Bikes', null, 'Turn heads as you ride through town and visit all Branson''s shops and restaurants. From Branson''s Ferris Wheel all the way downtown, around the Branson Landing and along Taneycomo''s lakefront. Totally Rad E-Bikes is geared towards providing our customers with a exciting way to see Branson on the fastest growing form of personal transportation. Within seconds of riding these e-bikes will instantly feel the "fun factor" Super73 has to offer.', '1008 W Farmer St', 'Ozark', 'MO', '65721', '(417) 551-4344', null, 'https://www.totallyradebikes.com/', 'https://www.facebook.com/totallyradebikes', null, null, null, null, '[]'::jsonb, false, true, 111) on conflict (slug) do nothing;
