insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('escape-code', 'Escape Code', null, 'Escape Rooms are exploding all across America and around much of the world, especially in Asia and Europe, and we can''t really be surprised. Being immersed as a key character in an exciting story while searching and investigating a themed environment is sure to excite anyone''s sense of adventure!', '4560 North Gretna Rd', 'Branson', 'MO', '65616', '(417) 365-7999', null, 'https://www.escapecode.tv/', 'https://www.facebook.com/escapecodegame', null, null, null, null, '[]'::jsonb, false, true, 112) on conflict (slug) do nothing;
