insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('sagas-mystery-events', 'Sagas Mystery Events', null, 'Sagas is a unique compilation of mystery theater and escape games. Whether you are looking for a fun team-building activity or you just want a little after-dinner entertainment, Sagas will prove to be an event to remember. The affair begins with hot drinks and sweet treats as you get ready for a night of mystery solving. Then grab a flashlight, hunt for clues in the 3200 square foot property, discover secrets and solve puzzles as you rush to unravel the mystery! You may encounter live actors as you move from room to room, but trust no one. There is a killer among you!', '4554 North Gretna Rd', 'Branson', 'MO', '65616', '(417) 365-7999', null, 'https://www.sagas.tv/', 'https://www.facebook.com/sagasbranson/', null, null, null, null, '[]'::jsonb, false, true, 113) on conflict (slug) do nothing;
