insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('branson-board-game-cafe', 'Branson Board Game Cafe', null, 'For just $5 per person ($4 for groups of 5 or more and $20 max for a family) you can play board games all day/evening. Our library has over 800 games in various categories as well as jigsaw puzzles so there is something for everyone. You can enjoy cappuccinos, lattes, deli sandwiches, and snacks while playing the games. We also have board games for sale. There is a private room that can be used for birthday parties or other celebrations.', '103 S Business Hwy 165', 'Branson', 'MO', '65616', '(417) 244-4373', null, 'https://bransonboardgamecafe.com/', 'https://www.facebook.com/bransonboardgame/', null, null, null, null, '[]'::jsonb, false, true, 115) on conflict (slug) do nothing;
