insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('branson-bowling', 'Branson Bowling - Lanes, Grill, Arcade', null, 'Welcome to Branson Bowling, formerly known as Woodland Lanes, a community favorite that''s being re-imagined for a new generation of fun! Enjoy our 16 classic lanes, a lively arcade, a mouth-watering grill, and a welcoming atmosphere that brings families, friends, and teams together. Whether you''re celebrating, competing, or just kicking back, we''ve got everything you need to make memories that roll.', '2126 E State Hwy 76', 'Branson', 'MO', '65616', '(417) 335-2695', null, 'https://www.bransonbowling.com/', 'https://www.facebook.com/profile.php?id=61581895132522', null, null, null, null, '[]'::jsonb, false, true, 116) on conflict (slug) do nothing;
