insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('rise-play-park', 'Rise Play Park', 'Indoor Playground and Kids Birthday Parties', 'We are an indoor playground for kids 0-10. From our imagination grocery store, pizza place, ice cream shop, vet office, & farm modeled & named after local businesses to our 16ft pirate ship your kids will have a blast. 0-2? We have a space for them too!', '3300 Gretna Rd Suite A', 'Branson', 'MO', '65616', '(623) 216-5466', null, 'https://riseplaypark.com/', 'https://www.facebook.com/riseplaypark/', null, null, null, null, '[]'::jsonb, false, true, 117) on conflict (slug) do nothing;
