insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('best-western-center-pointe-inn', 'Best Western Center Pointe Inn', null, 'Location, location, location! This award-winning hotel is the most requested Best Western in Missouri! Best Western Center Pointe Inn is within walking distance of many prime attractions, theatres, and restaurants, such as the Titanic Museum, the new Beyond the Lens museum, and Clay Cooper Theatre, just to name a few. Montana Mike''s Steakhouse is right on site. Amenities include elevators, free hot breakfast, indoor and outdoor saltwater pool and hot tub, sauna, exercise room, game room, on-site ticket service and gift shop, guest laundry, sun deck, picnic area, level parking, and both interior and exterior corridors. Rooms feature free Wi-Fi, flat screen TV, microwave, refrigerator, iron/ironing board, hair dryer, in-room coffee maker, and desk area, with two-sink vanity available in some rooms.', null, 'Branson', 'MO', null, '(417) 334-1894', null, 'https://www.myerhospitality.com/best-western-center-pointe-inn/', null, null, 'https://www.google.com/maps/place/Best+Western+Center+Pointe+Inn/@36.6390953,-93.2813863,17z/data=!3m1!4b1!4m8!3m7!1s0x87cf1bdf514eab7f:0x57dc83646b023db1!5m2!4m1!1i2!8m2!3d36.6390953!4d-93.2791976', '/legacy/best-western-center-pointe-inn.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57381@2x.jpg', '[{"label":"MyerHospitality.com","url":"http://MyerHospitality.com"}]'::jsonb, false, true, 118) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'best-western-center-pointe-inn' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('best-western-music-capital-inn', 'Best Western Music Capital Inn', null, 'The award-winning Best Western Music Capital Inn is one of America''s Top Best Westerns, as well as top ranked on TripAdvisor, so you know you''ll find the best in Ozark hospitality. Be sure to visit our lobby for one of the most unique chandeliers in Branson! If it''s location you''re looking for, we are conveniently located near some of Branson''s top shows and attractions, like Pierce Arrow Theater and IMAX Entertainment Complex. Amenities include elevators, free hot breakfast, indoor saltwater pool and hot tub, sauna, exercise room, game room, on-site ticket service and gift shop, guest laundry, sun deck, picnic area, level parking, and interior corridors. Rooms feature free Wi-Fi, flat screen TV, microwave, refrigerator, iron/ironing board, hair dryer, in-room coffee maker, desk area, and two-sink vanity.', null, 'Branson', 'MO', null, '(417) 334-8378', null, 'https://www.myerhospitality.com/best-western-music-capital-inn/', null, null, 'https://www.google.com/maps/place/Best+Western+Music+Capital+Inn/@36.6521855,-93.2842103,17z/data=!3m1!4b1!4m8!3m7!1s0x87cf1b61c7517227:0x56a52fc6cc09602a!5m2!4m1!1i2!8m2!3d36.6521855!4d-93.2820216', '/legacy/best-western-music-capital-inn.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57385@2x.jpg', '[{"label":"MyerHospitality.com","url":"http://MyerHospitality.com"}]'::jsonb, false, true, 119) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'best-western-music-capital-inn' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('comfort-inn-suites-branson-meadows', 'Comfort Inn & Suites Branson Meadows', null, 'This 3-time Ring of Honor winner, awarded for being in the top 1% of Choice Hotels, is sure to impress! Comfort Inn & Suites Branson Meadows sits on one of the highest points in Branson, offering a million dollar view of the Ozark area. You''ll enjoy the mountain lodge atmosphere that creates an experience unlike any other in Branson. Be sure to take pictures next to our big bear, eagle, or moose! Besides the unique theme and wonderful views, the hotel is near Sight & Sound Theatre, the Mansion Theatre, and the Shoppes at Branson Meadows. Amenities include elevators, free hot breakfast, indoor saltwater pool and hot tub, sauna, exercise room, game room, on-site ticket service and gift shop, guest laundry, sun deck, picnic area, level parking, and interior corridors. Rooms feature free Wi-Fi, flat screen TV, microwave, refrigerator, iron/ironing board, hair dryer, in-room coffee maker, desk area, and two-sink vanity. At Comfort Inn & Suites, our number one priority is ensuring your satisfaction. We strive to help you feel comfortable and at home.', null, 'Branson', 'MO', null, '(417) 335-4731', null, 'https://www.myerhospitality.com/comfort-inn-branson-meadows/', null, null, 'https://goo.gl/maps/iFmoYyATffCH2ByY9', '/legacy/comfort-inn-suites-branson-meadows.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57388@2x.jpg', '[{"label":"MyerHospitality.com","url":"http://MyerHospitality.com"}]'::jsonb, false, true, 120) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'comfort-inn-suites-branson-meadows' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('comfort-inn-at-thousand-hills', 'Comfort Inn at Thousand Hills', null, 'Comfort Inn at Thousand Hills is ranked in the top 3% in the country! It is also a 2020 Choice Platinum award winner and past winner of numerous Gold and Platinum Awards. As one of Branson''s premier resort hotels, it has a relaxing atmosphere, overlooking the Thousand Hills Golf course, yet is close to all the action! We are close to shopping like The Grand Village and Tanger Outlets and theaters/shows like Branson''s Famous Baldknobbers, King''s Castle Theatre, and Andy Williams Performing Arts Centre & Theatre. Amenities include elevators, free hot breakfast, indoor saltwater pool and hot tub, sauna, exercise room, game room, on-site ticket service and gift shop, guest laundry, meeting room, sun deck, picnic area, level parking, and interior corridors. Rooms feature free Wi-Fi, flat screen TV, microwave, refrigerator, iron/ironing board, hair dryer, in-room coffee maker, desk area, and two-sink vanity.', null, 'Branson', 'MO', null, '(417) 335-4727', null, 'https://www.myerhospitality.com/comfort-inn-thousand-hills/', null, null, 'https://goo.gl/maps/hp6V7BrUg5P4WNCp6', '/legacy/comfort-inn-at-thousand-hills.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57391@2x.jpg', '[{"label":"MyerHospitality.com","url":"http://MyerHospitality.com"}]'::jsonb, false, true, 121) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'comfort-inn-at-thousand-hills' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('holiday-inn-express-green-mountain-drive', 'Holiday Inn Express – Green Mtn. Drive', null, 'The perfect combination of location and luxury! Holiday Inn Express – Green Mtn. Drive is located in the heart of the theatre district, with Branson''s Famous Baldknobbers and Andy Williams Performing Arts Centre & Theatre nearby. It is also close to some great shopping areas such as The Grand Village and Tanger Outlets, as well as golfing at Thousand Hills. You will also find many dining options nearby, like Florentina''s Ristorante Italiano, Mel''s Hard Luck Diner, and Shorty Small''s. Amenities include elevators, free hot breakfast, indoor saltwater pool and hot tub, sauna, exercise room, on-site ticket service and gift shop, guest laundry, sun deck, picnic area, level parking, and interior corridors. Rooms feature free Wi-Fi, flat screen TV, microwave, refrigerator, iron/ironing board, hair dryer, in-room coffee maker, desk area, and two-sink vanity.', null, 'Branson', 'MO', null, '(417) 336-2100', null, 'https://www.myerhospitality.com/holiday-inn-express/', null, null, 'https://goo.gl/maps/3wwBbamVJvkiFM5m7', '/legacy/holiday-inn-express-green-mountain-drive.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57393@2x.jpg', '[{"label":"MyerHospitality.com","url":"http://MyerHospitality.com"}]'::jsonb, false, true, 122) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'holiday-inn-express-green-mountain-drive' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('quality-inn-west', 'Quality Inn West', null, 'The 2020 Platinum Award-Winning Quality Inn West is one of Branson''s best midscale hotels. It''s the closest hotel in Branson to Silver Dollar City, plus it''s surrounded by top Branson theaters and dining experiences. Red Lobster, Olive Garden, Cracker Barrel, Little Hacienda, and IMAX Entertainment Complex are all within walking distance! You''ll appreciate the attention to detail in the landscaping filled with flowers, trees, and beautiful green space, as well as the sundeck and patio areas. Amenities include elevators, free hot breakfast, indoor saltwater pool and hot tub, on-site ticket service at the front desk, guest laundry, sun deck, picnic area, level parking, and exterior corridors. Rooms feature free Wi-Fi, flat screen TV, microwave, refrigerator, iron/ironing board, hair dryer, in-room coffee maker, and desk area. If you are looking for a quality place to stay at an excellent value, The Quality Inn West is for you!', null, 'Branson', 'MO', null, '(417) 334-8694', null, 'https://www.myerhospitality.com/quality-inn-west/', null, null, 'https://goo.gl/maps/Mp53SEE8ZWAj1cWq5', '/legacy/quality-inn-west.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57396@2x.jpg', '[{"label":"MyerHospitality.com","url":"http://MyerHospitality.com"}]'::jsonb, false, true, 123) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'quality-inn-west' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('rosebud-inn', 'Rosebud Inn', null, 'The Rosebud Inn is ideally located on Branson''s Roark Valley Road. The motel''s excellent location provides easy access to Branson Shows such as The Mansion, the New Sight and Sound Theater, White House Theater, Branson Variety Theater and Shoji Tabuchi Theater. Other Branson Attractions are also close by including Ride the Ducks, Titanic Museum, Celebration City and 8 miles from Silver Dollar City. If shopping is a part of your Branson getaway, The Rosebud Inn is close to Tanger Outlet Center, the Branson Mill, Red Roof Mall and only 3 miles to the new Branson Landing on Lake Taneycomo.', 'Roark Valley Road', 'Branson', 'MO', null, '(417) 336-4000', null, 'http://rosebudinn.com/', null, null, 'https://www.google.com/maps/place/Rosebud+Inn/@36.6471123,-93.2656175,17z/data=!3m1!4b1!4m8!3m7!1s0x87cf035429bc6381:0x20367b768b64d106!5m2!4m1!1i2!8m2!3d36.647108!4d-93.2634288', '/legacy/rosebud-inn.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57346@2x.jpg', '[]'::jsonb, false, true, 124) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'rosebud-inn' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('the-duttons-inn', 'The Duttons Inn', null, 'Our rooms are clean and economical. All rooms are non-smoking and we do not allow pets. Children 12 and under are free. We have 2 ground levels and also an elevator. While we do not have a pool at the Dutton Inn we are located across the street from White Water.', null, 'Branson', 'MO', null, '(417) 332-2772', null, 'https://www.duttoninn.com/', null, null, 'https://www.google.com/maps/place/The+Dutton+Inn/@36.6424333,-93.2890147,17z/data=!3m1!4b1!4m8!3m7!1s0x87cf1c9ae289546b:0xbab19ab4fade7947!5m2!4m1!1i2!8m2!3d36.642429!4d-93.286826', '/legacy/the-duttons-inn.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57348.jpg', '[]'::jsonb, false, true, 125) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'the-duttons-inn' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('the-branson-hotel', 'The Branson Hotel', 'ADULTS ONLY', 'Located only 3 1/2 blocks from the Branson Landing. We would like our guests to experience the unforgettable charm of The Branson Hotel. Because we are an ADULTS ONLY hotel, we offer that peaceful environment that you may not always get at home. You will be surrounded by the rich history of the 1900''s, but fully restored in the luxury of the 21st century. Those review cards we ask our guests to fill out are being read and taken into consideration. Many of our guests are requesting we start a LOYALTY PROGRAM for all returning guests. We have chosen to start such a program. If you have stayed with us in the past we would like to ask you to call the hotel directly to book your next stay with us. Upon calling our hotel you will automatically receive a special LOYALTY DISCOUNT.', null, 'Branson', 'MO', null, '(417) 544-9814', null, 'https://thebransonhotel.com/', null, null, 'https://www.google.com/maps/place/The+Branson+Hotel/@36.6439262,-93.221144,17z/data=!3m1!4b1!4m8!3m7!1s0x87cf0378646ea64f:0x86215ca120941cf8!5m2!4m1!1i2!8m2!3d36.6439219!4d-93.2189553', '/legacy/the-branson-hotel.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57350.jpg', '[]'::jsonb, false, true, 126) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'the-branson-hotel' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('hunters-friend-resort', 'Hunter''s Friend Resort', null, 'One of the closest resorts to Silver Dollar City and Indian Point Marina. If you hate traffic and simply want to spend more time on vacation and less time staring at taillights from the car sitting at a dead stop in front of you – reserve with us!! We are located 2 miles straight south (no stop signs or traffic lights) from Silver Dollar City and directly across from Indian Point Marina. Our resort is perfect for vacationers who want to find the perfect place to stay that is extraordinarily clean, affordable, and close to just about everything Branson has to offer. We even have a Wal Mart Supercenter less than 10 minutes away!', null, 'Branson', 'MO', null, null, null, 'http://www.huntersfriendresort.com/', null, null, 'https://www.google.com/maps/place/Hunter%27s+Friend+Resort/@36.6273837,-93.3471173,17z/data=!3m1!4b1!4m8!3m7!1s0x87cf1ea20591f217:0x2c3bd8c8dad564f0!5m2!4m1!1i2!8m2!3d36.6273794!4d-93.3449286', '/legacy/hunters-friend-resort.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57358@2x.jpg', '[]'::jsonb, false, true, 127) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'hunters-friend-resort' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('table-rock-sunset-condos', 'Table Rock Sunset Condos', null, 'Table Rock Sunset Condos were built in 2005. The property sits just a few feet away from Table Rock Lake. It''s located at the end of Indian Point Rd, 3 miles South of Silver Dollar City. Property has 2 buildings with 6 condominiums in each building. There''s an outdoor pool, private parking, a restaurant/bar within walking distance. Indian Point Marina is only 600 yards away from the property. The air-conditioned units are furnished with tiled floors and feature a private bathroom, a flat-screen TV, free WiFi, closet, a living room, an equipped kitchen, patio and views over the lake. A dishwasher, a microwave and fridge are also available, as well as a coffee machine.', 'Indian Point Rd', 'Branson', 'MO', null, null, null, 'https://www.google.com/travel/hotels/entity/CgoI0LnJxv3smYIPEAE/prices', null, null, 'https://www.google.com/maps/dir//Table+Rock+Sunset+Condos/data=!4m6!4m5!1m1!4e2!1m2!1m1!1s0x87cf1e9a183bdd57:0xf046767d8d25cd0', '/legacy/table-rock-sunset-condos.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57362@2x.jpg', '[]'::jsonb, false, true, 128) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'table-rock-sunset-condos' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('rockwood-resort-condos', 'Rockwood Resort Condo''s', null, 'Rockwood Resort is the #1 Luxury Resort destination on Table Rock Lake. Located on Indian Point just 2 miles from Silver Dollar City and 5 miles from the strip in Branson. With tree-lined shores and crystal clear water, it is no wonder that Table Rock Lake on Indian Point is the Ozarks top vacation destinations. Our condos are over 1600 square feet and offer gourmet kitchens with granite countertops and high-end appliances. Each of our condos is artfully decorated and fully stocked with everything you need to make your stay exceptional while making Rockwood Resort your home away from home.', 'Indian Point', 'Branson', 'MO', null, null, null, 'https://bookrockwood.com/', null, null, 'https://www.google.com/maps/place/Rockwood+Resort/@36.6407772,-93.3434512,17z/data=!3m1!4b1!4m8!3m7!1s0x87cf1ea9485da271:0xe3ec7239c5bd408b!5m2!4m1!1i2!8m2!3d36.6407729!4d-93.3412625', '/legacy/rockwood-resort-condos.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57366@2x.jpg', '[]'::jsonb, false, true, 129) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'rockwood-resort-condos' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('americinn-by-wyndham-branson', 'AmericInn by Wyndham Branson & Conference Center', null, 'AmericInn by Wyndham Branson & Conference Center is a favorite with business and vacation travelers thanks to comfortable guest rooms, an indoor pool, and free WiFi, breakfast, and a nightly dessert bar. Off US-65, 13 miles from Branson Airport (BKG) and 55 miles from Springfield–Branson National Airport (SGF), our non-smoking hotel is surrounded by restaurants, shopping malls like Tanger® Outlets Branson, and attractions such as Adventure Ziplines of Branson and Hollywood Wax Museum. We''re also a quick drive from the College of the Ozarks®.', '275 Tanger Blvd', 'Branson', 'MO', '65616', null, null, 'https://www.wyndhamhotels.com/americinn/branson-missouri/americinn-branson-and-conference-center/overview', null, null, 'https://www.google.com/maps/dir//275+Tanger+Blvd,+Branson,+MO+65616/@36.6427747,-93.3474233,12z', '/legacy/americinn-by-wyndham-branson.png', 'https://www.bransonlocalbusinesses.com/index_htm_files/58574@2x.png', '[]'::jsonb, false, true, 130) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'americinn-by-wyndham-branson' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('lilleys-landing-resort-marina', 'Lilley''s Landing Resort & Marina', null, 'Lilleys'' Landing Resort and Marina in Branson, Missouri, may be just the year-round spot you''re looking for to enjoy both the tourist sites and the restive Ozarks waterfront along Lake Taneycomo. Nestled between gently sloping pasture land and the 300-foot bluffs on the opposite bank, the grounds are buffered to traffic bustle, even though the Highway 76 Country Blvd. "strip" is just two miles away.', '367 River Ln', 'Branson', 'MO', '65616', null, null, 'https://lilleyslanding.com/', null, null, 'https://www.google.com/maps?ll=36.613943,-93.245654&z=6&t=m&hl=en-US&gl=US&mapclient=embed&daddr=367+River+Ln+Branson,+MO+65616@36.6139432,-93.24565439999999', '/legacy/lilleys-landing-resort-marina.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57373@2x.jpg', '[]'::jsonb, false, true, 131) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'lilleys-landing-resort-marina' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('branson-shenanigans-rv-park', 'Branson Shenanigans RV Park and Campground', null, 'Just blocks away from the strip our location along with amazing service makes us one of the best and most popular places to stay in Branson, Missouri. It serves as a place to relax as well as find adventure. We are short drives from the Titanic Museum, Branson Ferris Wheel, Hollywood Wax Museum, Ripley''s Believe it or Not!, and other exciting attractions. Our forest RV Park serves to provide seclusion as well as a quiet place to sleep, even when you are so close to the action.', null, 'Branson', 'MO', null, null, null, 'https://www.bransonrvparks.com/', null, null, 'https://www.google.com/maps/place/Branson+Shenanigans+RV+Park/@36.6461017,-93.2939947,17z/data=!3m1!4b1!4m8!3m7!1s0x87cf1c8389a95511:0xec887eac7ac058b8!5m2!4m1!1i2!8m2!3d36.6460974!4d-93.291806', '/legacy/branson-shenanigans-rv-park.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57376@2x.jpg', '[]'::jsonb, false, true, 132) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'branson-shenanigans-rv-park' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('lynina-inn', 'Lynina Inn', null, 'Lynina Inn, located on Shepherd of the Hills Expressway, is only minutes from a vast selection of Branson''s nationally acclaimed entertainment and attractions; many within walking distance. Take a stroll from our property to some of the finest food in Branson at Paradise Grill, Red Lobster, Golden Corral or McFarlain''s from there it is only a short walk to The Shoji Tabuchi Theater, Pierce Arrow Theater, the IMAX Entertainment Complex and more! Hop in your car and a drive of five miles or less will take you to an astounding selection of entertainment, fine dining, attractions and shopping! Visit Silver Dollar City, the new Sight & Sound Theater, the White House Theater, the Titanic Museum, the new Branson Landing or one of the three large factory direct malls just to name a few. Come relax in our comfortable accommodations, wake up to our Deluxe Hot Continental Breakfast and make a splash in our large outdoor swimming pool. One stay and you will be planning your next trip to Branson and the Lynina Inn. Call today and let our friendly staff help you begin making great vacation memories.', 'Shepherd of the Hills Expressway', 'Branson', 'MO', null, null, null, 'https://www.lyninainn.com/', null, null, 'https://www.google.com/maps/dir//Lynina+Inn/data=!4m6!4m5!1m1!4e2!1m2!1m1!1s0x87cf1b5f1b07e193:0xbc3d1d79be19c91a', '/legacy/lynina-inn.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57403@2x.jpg', '[]'::jsonb, false, true, 133) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'lynina-inn' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('cedar-hollow-resort', 'Cedar Hollow Resort', null, 'Welcome to Cedar Hollow Resort on Table Rock Lake near Galena, Missouri. This lakeside retreat, established in 1960, is now under new ownership but still remains authentic in its original charm. There are nine fully furnished units with kitchens and room for two to six guests. The covered boat dock has six boat slips available on a first come-first serve basis. Nearby attractions include Silver Dollar City, White Water Amusement Park, the Branson Theaters, and many other local and regional points of interest.', null, 'Galena', 'MO', null, null, null, 'https://resortatcedarhollow.com/', null, null, 'https://www.google.com/maps/dir//Cedar+Hollow+Resort/data=!4m6!4m5!1m1!4e2!1m2!1m1!1s0x87cf25834f658bbb:0x62309464821e3a43', '/legacy/cedar-hollow-resort.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/57408.jpg', '[]'::jsonb, false, true, 134) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'cedar-hollow-resort' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('the-retro-hotel', 'The Retro Hotel', 'Wake up like a rockstar!', 'Wake up like a rockstar! The rooms at The Retro have been comfortably updated, and have wifi, air conditioning, ensuite bathroom with tub, shower and toiletries, flat-screen TV, as well as a mini-fridge and microwave. At The Retro, you''re in the heart of it all! The Retro is ideally located, literally across the street from Tanger Outlets, and minutes from Branson''s incredible family attractions, theaters, and restaurants. Silver Dollar City is only 6.4 miles from The Retro, and gorgeous Table Rock State Park is just 7.3 miles away. Our friendly and efficient staff are also local experts! We often have discount coupons at the front desk, and can help you book tickets. Ask us about where to eat, what to see, and what to do! Our team is ready to share insider tips to make your stay unforgettable. We offer free Hot breakfast Saturday and Sundays featuring house-made eggs, hash browns, biscuits, and gravy. We also have free continental breakfast during weekdays. We also have a gorgeous pool! Take a refreshing dip in the deepest pool in Branson. It''s the perfect spot to unwind after a day of exploring Branson. Swan floats and pool towels included.', '2330 W 76 Country Blvd', 'Branson', 'MO', '65616', null, null, 'https://www.theretrohotel.com/', null, null, 'https://www.google.com/maps/dir//The+Retro+Hotel,+2330+W+76+Country+Blvd,+Branson,+MO+65616/@37.8011536,-95.2863965,8z', '/legacy/the-retro-hotel.png', 'https://www.bransonlocalbusinesses.com/index_htm_files/62735@2x.png', '[]'::jsonb, false, true, 135) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'the-retro-hotel' and c.slug = 'hotels' on conflict do nothing;
insert into public.businesses (slug, name, tagline, description, address, city, state, zip, phone, email, website, facebook, instagram, maps_url, logo_url, source_image_url, extra_links, featured, is_published, sort_order) values ('gobblers-mountain-getaway', 'Gobblers Mountain Getaway', null, 'Nestled in the hills of Branson West, Missouri, Gobblers Mountain Getaway is a private Ozarks estate designed for adventurous escapes, family gatherings and intimate celebrations. Just minutes from Branson entertainment, Silver Dollar City and Table Rock Lake, our luxury vacation rental offers the perfect blend of mountain seclusion and convenient access to everything the area has to offer! With four spacious bedrooms, expansive gathering areas, gorgeous outdoor spaces and stunning scenic views of the surrounding Ozarks, the home is ideal for: Family Vacations Near Branson; Bed-and-Breakfast Style Stays; Weekend Retreats; Intimate Weddings & Elopements; Special Events & Milestone Celebrations. Whether you''re planning a relaxing getaway or a small mountain wedding, Gobblers Mountain Getaway offers privacy, comfort and a setting designed for connection.', '670 Gobblers Mountain Rd', 'Branson West', 'MO', '65737', null, null, 'https://www.gobblersmountaingetaway.com/', null, null, 'https://www.google.com/maps/dir//670+Gobblers+Mountain+Rd,+Branson+West,+MO+65737/@37.7998147,-95.2890535,8z', '/legacy/gobblers-mountain-getaway.jpg', 'https://www.bransonlocalbusinesses.com/index_htm_files/62740@2x.jpg', '[]'::jsonb, false, true, 136) on conflict (slug) do nothing;
insert into public.business_categories (business_id, category_id) select b.id, c.id from public.businesses b, public.categories c where b.slug = 'gobblers-mountain-getaway' and c.slug = 'hotels' on conflict do nothing;
